'use strict';
const career = new Career((()=>{try{return localStorage;}catch{return null;}})());
let expandedRoundId='',lastSettlement=null;
function money(value){return '$'+Math.floor(Number.isFinite(value)?value:0);}
function gameTime(e,precise=career.data.clockEnabled){const total=e.clockMinutes,hour=Math.floor(total/60)||12;return precise?`${hour}:${String(total%60).padStart(2,'0')}`:String(hour);}
function settleExpanded(){const paid=career.settle(engine,expandedRoundId);if(!paid.duplicate||!lastSettlement)lastSettlement=paid;updateCareerUI();return lastSettlement;}
function settlementHTML(){if(!lastSettlement)return'';return `<div class="pay-slip"><strong>ЗА СМЕНУ: +${money(lastSettlement.total)}</strong><span>Оплата ${money(lastSettlement.salary)} · энергия +${money(lastSettlement.energy||0)} · комфорт +${money(lastSettlement.comfort||0)}</span><span>На счету ${money(career.data.wallet)}</span></div>`;}
function updateCareerUI(){$('menuWallet').textContent=money(career.data.wallet);if(!career.saved)toast('Не удалось сохранить прогресс. Проверь доступ к локальному хранилищу.');}
function gadgetIcon(type){const paths={clock:'<circle cx="32" cy="32" r="22"/><path d="M32 16v17l11 7M24 4h16"/>',battery:'<rect x="12" y="17" width="38" height="30" rx="3"/><path d="M50 25h5v14h-5M20 25v14M28 25v14M36 25v14"/>',fan:'<circle cx="32" cy="27" r="21"/><circle cx="32" cy="27" r="4"/><path d="M32 23q-14-23-17-3l13 8M36 27q26-1 13 13l-16-9M30 31q-10 24-19 6l16-10M32 48v10M17 59h30"/>',charge:'<path d="M36 5L16 35h15l-3 24 22-33H35z"/>'};return `<svg viewBox="0 0 64 64" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2">${paths[type]||paths.charge}</svg>`;}
function showShop(){if(view==='playing'||view==='intro'||view==='jump')return;Sound.ambient(false);showModal(`<div class="shop-heading"><div><small>FAZBEAR EMPLOYEE STORE</small><h2>МАГАЗИН СМЕНЩИКА</h2></div><button id="shopClose" aria-label="Закрыть магазин">×</button></div><div class="shop-account"><strong>${money(career.data.wallet)}</strong><span>Заработано ${money(career.data.earned)} · смен завершено ${career.data.shifts}</span></div><p class="shop-rule">Все купленные фигурки можно поставить вместе. Их бонусы складываются со следующей смены.</p><div class="shop-grid">${SHOP_ITEMS.map(item=>{const owned=career.owns(item.id),equipped=career.data.equipped.includes(item.id),canBuy=career.data.wallet>=item.price&&(item.id!=='reserve'||career.data.reserve<9);let controls='';if(item.type==='toy'&&owned)controls=`<button data-equip="${item.id}" class="shop-action ${equipped?'installed':''}" >${equipped?'Убрать со стола':'Поставить на стол'}</button>`;else if(item.id==='clock'&&owned)controls=`<button id="shopClock" class="shop-action ${career.data.clockEnabled?'installed':''}">${career.data.clockEnabled?'ВЫКЛЮЧИТЬ ЧАСЫ':'ВКЛЮЧИТЬ ЧАСЫ'}</button>`;else if(owned)controls='<span class="shop-owned">УЛУЧШЕНИЕ УСТАНОВЛЕНО</span>';else controls=`<button data-buy="${item.id}" class="shop-action" ${canBuy?'':'disabled'}>Купить · ${money(item.price)}</button>`;return `<article class="shop-item ${equipped?'equipped':''}"><div class="item-image">${item.texture?`<img src="${assetURL('Textures/CustomNight/'+item.texture+'.png')}" alt="Игрушка ${item.name}">`:gadgetIcon(item.icon)}</div><div class="item-kind">${item.type==='toy'?'ФИГУРКА':item.type==='consumable'?'РАСХОДНИК · В ЗАПАСЕ '+career.data.reserve:item.type==='device'?'ПРИБОР':'УЛУЧШЕНИЕ'}</div><h3>${item.name}</h3><p>${item.description}</p>${controls}</article>`;}).join('')}</div><div class="shop-footer"><span>На столе: ${career.data.equipped.length}/4 · ${career.data.equipped.map(id=>career.item(id).name).join(', ')||'пока пусто'}</span><button id="shopBack">Вернуться в меню →</button></div>`);$('modalCard').classList.add('shop-card');$('shopClose').onclick=goMenu;$('shopBack').onclick=goMenu;document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{const result=career.buy(b.dataset.buy);if(result.ok){Sound.init().then(()=>Sound.tone(700,.1,.1,'sine',1100));showShop();toast(career.item(b.dataset.buy).name+' куплено');}else toast(result.reason);updateCareerUI();});document.querySelectorAll('[data-equip]').forEach(b=>b.onclick=()=>{const result=career.equip(b.dataset.equip);if(result.ok)showShop();else toast(result.reason);});if($('shopClock'))$('shopClock').onclick=()=>{career.toggleClock();showShop();};}
function toggleExactClock(){if(!career.toggleClock())return;updateHUD();Sound.tone(700,.04,.08);}
function useEmergencyCharge(){if(!active())return;if(career.data.reserve<=0){toast('Нет аварийного заряда. Его можно купить между сменами.');return;}if(!engine.useReserve()){toast(engine.reserveUsed?'Один заряд за смену уже использован.':'Батарея уже полная.');return;}career.consumeReserve();processEvents();updateHUD();toast('Аварийная батарея: +20% энергии.');}
function updateExpandedHUD(){if(!engine)return;$('shiftWallet').textContent=money(career.data.wallet);$('temperature').textContent=Math.floor(engine.temperature)+'°C'+(engine.temperature>40?' · ДЕЗОРИЕНТАЦИЯ':engine.temperature>=35?' · ТЕПЛО':'');$('temperature').classList.toggle('hot',engine.temperature>40);$('fanSwitch').textContent='F · ВЕНТИЛЯТОР '+(engine.fanOn&&engine.power>0?'ВКЛ':'ВЫКЛ');$('fanSwitch').setAttribute('aria-pressed',String(engine.fanOn&&engine.power>0));$('fanSwitch').disabled=engine.monitor||engine.power<=0;$('reserveButton').textContent='B · ЗАРЯД '+career.data.reserve;$('reserveButton').disabled=career.data.reserve===0||engine.reserveUsed||engine.power>=engine.maxPower;$('clockSwitch').hidden=!career.owns('clock');$('clockSwitch').textContent='ЧАСЫ '+(career.data.clockEnabled?'ВКЛ':'ВЫКЛ');$('clockSwitch').setAttribute('aria-pressed',String(career.data.clockEnabled));$('time').title=career.owns('clock')?'Нажми, чтобы включить или выключить минуты':'Точные часы можно купить в магазине';document.documentElement.style.setProperty('--heat',String(engine.disorientation*.3));}
function drawExpandedOffice(){const ratio=canvas.width/innerWidth,{scale,ox,oy}=officeTransform(),unit=scale*ratio;career.data.equipped.forEach((id,i)=>{const im=assets['Textures/CustomNight/'+id+'.png'];if(!im)return;const x=([675,735,970,1030][i]-ox)*unit,y=(463-oy)*unit;ctx.fillStyle='#121416';ctx.fillRect(x-18*unit,y+15*unit,36*unit,6*unit);ctx.drawImage(im,x-19*unit,y-27*unit,38*unit,43*unit);});}

function installExpanded(){const exit=document.createElement('button');exit.id='demoExit';exit.className='secondary';exit.textContent='ВЫЙТИ ИЗ ДЕМОНСТРАЦИИ · ESC';exit.hidden=true;exit.onclick=goMenu;$('game').appendChild(exit);updateCareerUI();$('shop').onclick=showShop;$('clockSwitch').onclick=toggleExactClock;$('time').onclick=()=>{if(career.owns('clock'))toggleExactClock();};$('fanSwitch').onclick=()=>action('fan');$('fanTarget').onclick=()=>action('fan');$('reserveButton').onclick=useEmergencyCharge;
 // The original office loop already contains the fan: stop that loop with the fan.
 Sound.fan=function(on){this.ambient(Boolean(on));};}

function resetEndoDemo(){engine=new NightEngine(1,[5,0,0,0,5],()=>1);engine.elapsed=80;engine.monitor=true;engine.cam=9;engine.enemies[0].pos=2;}
async function showEndoDemo(){await loading;if(loadFailed)return;await Sound.init();goMenu();resetEndoDemo();view='demo';paused=false;customLevels=null;$('menu').hidden=true;$('modal').hidden=true;$('hud').hidden=false;$('demoExit').hidden=false;document.body.className='playing cameras endo-demo';last=performance.now()/1000;updateHUD();}
